mapper.select:
WITH resultData AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY awaiting_details_code ORDER BY requested_date) AS rn FROM ${tableName} WHERE delete_flag = false AND awaiting_details_code IN
#{code}
AND enterprise_code = #{enterpriseCode} AND delete_flag = 'f') SELECT * FROM resultData WHERE rn = 1

select a.awaiting_details_code,sum(this_count) as packageCount,count(1) as recordCount from ${awaitingTaskDetailsTableName} a INNER JOIN ${invoiceOrderTableName} b on a.invoice_order = b.primary_key where a.contract_code in
#{contractCode}
and a.delete_flag = false and a.enterprise_code = #{enterpriseCode} and b.packaged = true GROUP BY a.awaiting_details_code

with t as (select sum(tt.packageCount)
           from (SELECT a.awaiting_details_code,
                        SUM(this_count) AS packageCount
                 FROM ${awaitingTaskDetailsTableName} a
                          INNER JOIN ${invoiceOrderTableName} b
                                     ON a.invoice_order = b.primary_key
                 WHERE a.contract_code = #{contractCode}
                   AND a.delete_flag = FALSE
                   AND a.enterprise_code = #{enterpriseCode}
                   AND b.packaged = TRUE
                 GROUP BY A.awaiting_details_code) tt),

     t1 as (select sum(product_quantity)
            from ${awaitingDetailsTableName} a
            where a.contract_code = #{contractCode}
              and a.delete_flag = FALSE
              and a.enterprise_code = #{enterpriseCode}
            GROUP BY contract_code)
select t.* >= t1.*
from t,
     t1
